using App.Entities;
using Microsoft.EntityFrameworkCore;

namespace App;

/// <summary>The tables of the database, mapped as the database has them. It never migrates: the database already exists.</summary>
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Thing> Things => Set<Thing>();
    public DbSet<Kind> Kinds => Set<Kind>();
    public DbSet<Order> OrderRows => Set<Order>();
    public DbSet<Entry> Entries => Set<Entry>();
    public DbSet<Empty> Empties => Set<Empty>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.HasPostgresEnum("mood", new[] { "sad", "ok", "very happy" });

        model.Entity<Thing>(entity =>
        {
            entity.ToTable("things");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.Token).HasColumnName("token");
            entity.Property(e => e.Small).HasColumnName("small");
            entity.Property(e => e.Num).HasColumnName("num");
            entity.Property(e => e.Big).HasColumnName("big");
            entity.Property(e => e.Price).HasColumnName("price").HasPrecision(10, 2);
            entity.Property(e => e.R).HasColumnName("r");
            entity.Property(e => e.D).HasColumnName("d");
            entity.Property(e => e.Flag).HasColumnName("flag").IsRequired().HasDefaultValue(true);
            entity.Property(e => e.Born).HasColumnName("born");
            entity.Property(e => e.Opens).HasColumnName("opens");
            entity.Property(e => e.OpensTz).HasColumnName("opens_tz");
            entity.Property(e => e.At).HasColumnName("at").HasColumnType("timestamp without time zone");
            entity.Property(e => e.AtTz).HasColumnName("at_tz");
            entity.Property(e => e.Bin).HasColumnName("bin");
            entity.Property(e => e.Data).HasColumnName("data").HasColumnType("jsonb");
            entity.Property(e => e.Plain).HasColumnName("plain").HasColumnType("json");
            entity.Property(e => e.Feeling).HasColumnName("feeling").HasColumnType("mood").HasConversion(value => PgEnums.ToMood(value), value => PgEnums.FromMood(value));
            entity.Property(e => e.Tags).HasColumnName("tags").Metadata.SetTypeMapping(new NativeText("text[]"));
            entity.Property(e => e.Numbers).HasColumnName("numbers").Metadata.SetTypeMapping(new NativeText("integer[]"));
            entity.Property(e => e.Ip).HasColumnName("ip").Metadata.SetTypeMapping(new NativeText("inet"));
            entity.Property(e => e.Span).HasColumnName("span").Metadata.SetTypeMapping(new NativeText("interval"));
            entity.Property(e => e.Code).HasColumnName("code").HasMaxLength(5).IsFixedLength();
            entity.Property(e => e.Note).HasColumnName("note");
            entity.Property(e => e.Changed).HasColumnName("changed").HasDefaultValueSql("CURRENT_TIMESTAMP");
            entity.Property(e => e.Total).HasColumnName("total").HasPrecision(12, 2).HasComputedColumnSql("price * 2", stored: true);
        });

        model.Entity<Kind>(entity =>
        {
            entity.ToTable("kinds");
            entity.HasKey(e => new { e.Code, e.Day });
            entity.Property(e => e.Code).HasColumnName("code").HasMaxLength(10);
            entity.Property(e => e.Day).HasColumnName("day");
            entity.Property(e => e.Label).HasColumnName("label").HasMaxLength(30);
        });

        model.Entity<Order>(entity =>
        {
            entity.ToTable("Order", t =>
            {
                t.HasCheckConstraint("ck_Order_1", "\"group\" >= 0");
            });
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("Id");
            entity.Property(e => e.User).HasColumnName("user").HasMaxLength(40);
            entity.Property(e => e.Group).HasColumnName("group").IsRequired().HasDefaultValue(0);
            entity.Property(e => e.CustomerName).HasColumnName("customerName").HasMaxLength(60);
            entity.Property(e => e.Class).HasColumnName("class");
            entity.Property(e => e.Metadata).HasColumnName("metadata");
            entity.Property(e => e.Date).HasColumnName("date");
            entity.Property(e => e.Time).HasColumnName("time");
            entity.Property(e => e.Text).HasColumnName("text").HasMaxLength(20);
            entity.Property(e => e.List).HasColumnName("list");
            entity.Property(e => e.Str).HasColumnName("str").HasMaxLength(10);
            entity.Property(e => e.Int).HasColumnName("int");
            entity.Property(e => e.DueDate).HasColumnName("dueDate");
            entity.Property(e => e.ClosesAt).HasColumnName("closesAt");
            entity.Property(e => e.CreatedAt).HasColumnName("createdAt").HasColumnType("timestamp without time zone").HasDefaultValueSql("CURRENT_TIMESTAMP");
            entity.Property(e => e.KindCode).HasColumnName("kind_code").HasMaxLength(10);
            entity.Property(e => e.KindDay).HasColumnName("kind_day");
            entity.Property(e => e.ThingId).HasColumnName("thing_id");
            entity.Property(e => e.ParentId).HasColumnName("parentId");
            entity.HasIndex(e => e.CustomerName).IsUnique();
            entity.HasOne<Thing>()
                .WithMany()
                .HasForeignKey(e => e.ThingId)
                .OnDelete(DeleteBehavior.SetNull);
            entity.HasOne<Order>()
                .WithMany()
                .HasForeignKey(e => e.ParentId)
                .OnDelete(DeleteBehavior.NoAction);
            entity.HasOne<Kind>()
                .WithMany()
                .HasForeignKey(e => new { e.KindCode, e.KindDay })
                .OnDelete(DeleteBehavior.NoAction);
        });

        model.Entity<Entry>(entity =>
        {
            entity.ToTable("entries", "audit");
            entity.HasKey(e => e.EntryNo);
            entity.Property(e => e.EntryNo).HasColumnName("entry_no");
            entity.Property(e => e.OrderId).HasColumnName("orderId");
            entity.Property(e => e.Message).HasColumnName("message").HasMaxLength(200);
            entity.HasOne<Order>()
                .WithMany()
                .HasForeignKey(e => e.OrderId)
                .OnDelete(DeleteBehavior.Cascade);
        });

        model.Entity<Empty>(entity =>
        {
            entity.ToTable("empties");
            entity.HasKey(e => e.Id);
            entity.Property(e => e.Id).HasColumnName("id");
            entity.Property(e => e.Note).HasColumnName("note");
        });
    }
}

