            else
            {
                if (value is string text && text.Length > 200) errors.Add(new FieldError("message", "is longer than 200 characters"));
            }
        }
        {
            var orderId = values.TryGetValue("OrderId", out var givenOrderId) ? (long?)givenOrderId : current?.OrderId;
            if (orderId is not null && await uow.OrderRows.FindByIdAsync(orderId.Value) is null)
