using Microsoft.EntityFrameworkCore;
using Xunit;

namespace App.Tests;

/// <summary>The tests run on the database they were asked to.</summary>
public class DatabaseTests
{
    [Fact]
    public async Task IsTheOneTestDatabaseConnectionNames()
    {
        await using var database = await TestDatabase.OpenAsync();
        var value = await database.Db.Database.SqlQueryRaw<string>("SELECT current_database() AS \"Value\"").SingleAsync();
        Assert.Equal(database.Db.Database.GetDbConnection().Database, value);
    }
}

