using App;
using App.Common;
using App.Dtos;
using App.Entities;
using App.Errors;
using App.Services;
using Xunit;

namespace App.Tests;

/// <summary>The repository of the "empties" table, against the test database.</summary>
public class EmptyRepositoryTests : IAsyncLifetime
{
    private TestDatabase database = null!;

    /// <summary>The repositories over the test database, opened empty for every test</summary>
    private SqlUnitOfWork uow = null!;

    public async ValueTask InitializeAsync()
    {
        database = await TestDatabase.OpenAsync();
        uow = new SqlUnitOfWork(database.Db);
    }

    public async ValueTask DisposeAsync() => await database.DisposeAsync();

    [Fact]
    public async Task IsStoredAndReadBack()
    {
        var stored = await Factories.AddEmptyAsync(uow, 1);
        uow.Db.ChangeTracker.Clear();
        var found = await uow.Empties.FindByIdAsync(stored.Id);
        Assert.NotNull(found);
        Assert.Equal(stored.Id, found.Id);
    }

    [Fact]
    public async Task ListsRowsByKey()
    {
        await Factories.AddEmptyAsync(uow, 1);
        await Factories.AddEmptyAsync(uow, 2);
        var page = await uow.Empties.ListAsync(0, 1);
        Assert.Equal(2, page.Total);
        Assert.Single(page.Items);
    }

    [Fact]
    public async Task StoresTheChanges()
    {
        var stored = await Factories.AddEmptyAsync(uow, 1);
        stored.Note = "changed";
        await uow.Empties.UpdateAsync(stored);
        uow.Db.ChangeTracker.Clear();
        Assert.Equal("changed", (await uow.Empties.FindByIdAsync(stored.Id))!.Note);
    }

    [Fact]
    public async Task IsDeleted()
    {
        var stored = await Factories.AddEmptyAsync(uow, 1);
        await uow.Empties.DeleteAsync(stored);
        Assert.Null(await uow.Empties.FindByIdAsync(stored.Id));
    }
}

