using App;
using App.Entities;

namespace App.Tests;

/// <summary>Rows for the tests: valid values for every column, and the rows they point to.</summary>
internal static class Factories
{
    /// <summary>A valid Thing that is not stored yet; n makes its unique values differ.</summary>
    public static Thing NewThing(int n)
    {
        var entity = new Thing();
        entity.Token = Guid.Parse($"00000000-0000-4000-8000-{n:D12}");
        entity.Small = (short)(n);
        entity.Num = (n);
        entity.Big = (long)(n);
        entity.Price = (n % 10000) + 0.50m;
        entity.R = n + 0.5f;
        entity.D = n + 0.5;
        entity.Flag = true;
        entity.Born = new DateOnly(2026, 1, n % 28 + 1);
        entity.Opens = new TimeOnly(12, n % 60);
        entity.OpensTz = new DateTimeOffset(1970, 1, 1, 12, n % 60, 0, TimeSpan.Zero);
        entity.At = new DateTime(2026, 1, n % 28 + 1, 12, 0, 0);
        entity.AtTz = new DateTimeOffset(2026, 1, n % 28 + 1, 12, 0, 0, TimeSpan.Zero);
        entity.Bin = new byte[] { (byte)n };
        entity.Data = $"{{\"n\": {n}}}";
        entity.Plain = $"{{\"n\": {n}}}";
        entity.Feeling = "sad";
        entity.Tags = "{}";
        entity.Numbers = "{}";
        entity.Code = (n % 100000).ToString().PadLeft(5, '0');
        entity.Note = $"note-{n}";
        return entity;
    }

    /// <summary>A stored Thing.</summary>
    public static async Task<Thing> AddThingAsync(IUnitOfWork uow, int n)
    {
        var entity = NewThing(n);
        return await uow.Things.InsertAsync(entity);
    }

    /// <summary>A valid Kind that is not stored yet; n makes its unique values differ.</summary>
    public static Kind NewKind(int n)
    {
        var entity = new Kind();
        entity.Code = $"code-{n}";
        entity.Day = new DateOnly(2026, 1, n % 28 + 1);
        entity.Label = $"label-{n}";
        return entity;
    }

    /// <summary>A stored Kind.</summary>
    public static async Task<Kind> AddKindAsync(IUnitOfWork uow, int n)
    {
        var entity = NewKind(n);
        return await uow.Kinds.InsertAsync(entity);
    }

    /// <summary>A valid Order that is not stored yet; n makes its unique values differ.</summary>
    public static Order NewOrder(int n)
    {
        var entity = new Order();
        entity.User = $"user-{n}";
        entity.Group = (n);
        entity.CustomerName = $"customername-{n}";
        entity.Class = $"class-{n}";
        entity.Metadata = $"metadata-{n}";
        entity.Date = new DateOnly(2026, 1, n % 28 + 1);
        entity.Time = new TimeOnly(12, n % 60);
        entity.Text = $"text-{n}";
        entity.List = $"list-{n}";
        entity.Str = $"str-{n}";
        entity.Int = (n);
        entity.DueDate = new DateOnly(2026, 1, n % 28 + 1);
        entity.ClosesAt = new TimeOnly(12, n % 60);
        return entity;
    }

    /// <summary>A stored Order.</summary>
    public static async Task<Order> AddOrderAsync(IUnitOfWork uow, int n)
    {
        var entity = NewOrder(n);
        return await uow.OrderRows.InsertAsync(entity);
    }

    /// <summary>A valid Entry that is not stored yet; n makes its unique values differ.</summary>
    public static Entry NewEntry(int n)
    {
        var entity = new Entry();
        entity.Message = $"message-{n}";
        return entity;
    }

    /// <summary>A stored Entry, with the rows it points to.</summary>
    public static async Task<Entry> AddEntryAsync(IUnitOfWork uow, int n)
    {
        var parent0 = await AddOrderAsync(uow, n);
        var entity = NewEntry(n);
        entity.OrderId = parent0.Id;
        return await uow.Entries.InsertAsync(entity);
    }

    /// <summary>A valid Empty that is not stored yet; n makes its unique values differ.</summary>
    public static Empty NewEmpty(int n)
    {
        var entity = new Empty();
        entity.Note = $"note-{n}";
        return entity;
    }

    /// <summary>A stored Empty.</summary>
    public static async Task<Empty> AddEmptyAsync(IUnitOfWork uow, int n)
    {
        var entity = NewEmpty(n);
        return await uow.Empties.InsertAsync(entity);
    }
}

